import { expect, type Page, test } from '@playwright/test';

/** Browser checks for the static marketing pages in public/ (generated by tools/build_site.py). */

const PAGES = [
  '/',
  '/nganh/ban-le/',
  '/nganh/villa-homestay/',
  '/nganh/spa-salon/',
  '/nganh/giao-duc/',
  '/nganh/phan-mem/',
  '/tinh-nang/ban-hang-ai/',
  '/tinh-nang/binh-luan-facebook/',
  '/tinh-nang/hop-thu/',
  '/tinh-nang/dao-tao-ai/',
  '/tinh-nang/tro-ly-rapiz/',
  '/tinh-nang/khach-hang-thong-ke/',
  '/tich-hop/',
  '/bao-mat/',
  '/bang-gia/',
  '/dat-lich-demo/',
  '/ve-rapiz/',
];

/** Script errors, failed same-origin requests and any request leaving the site. */
function watch(page: Page, origin: string) {
  const problems: string[] = [];
  page.on('pageerror', (e) => problems.push(`error: ${e.message}`));
  page.on('requestfailed', (r) => problems.push(`failed: ${r.url()}`));
  page.on('response', (r) => {
    if (r.status() >= 400) problems.push(`${r.status()}: ${r.url()}`);
  });
  page.on('request', (r) => {
    if (!r.url().startsWith(origin) && !r.url().startsWith('data:')) {
      problems.push(`third party: ${r.url()}`);
    }
  });
  return problems;
}

const noOverflow = (page: Page) =>
  page.evaluate(() => document.documentElement.scrollWidth <= innerWidth);

for (const path of PAGES) {
  test(`${path} loads cleanly on desktop and phone`, async ({ page, baseURL }) => {
    const problems = watch(page, baseURL!);
    await page.setViewportSize({ width: 1440, height: 1000 });
    const response = await page.goto(path, { waitUntil: 'networkidle' });
    expect(response!.status()).toBe(200);
    await expect(page.locator('h1')).toHaveCount(1);
    expect(await noOverflow(page), 'overflow at 1440').toBe(true);
    await page.setViewportSize({ width: 390, height: 844 });
    expect(await noOverflow(page), 'overflow at 390').toBe(true);
    expect(problems).toEqual([]);
  });
}

test('header links to sign-in and the demo page; dropdowns open', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.goto('/bang-gia/');
  const header = page.locator('header.site-head');
  await expect(header.locator('.head-login')).toHaveAttribute('href', '/login');
  await expect(header.locator('.head-cta')).toHaveAttribute('href', '../dat-lich-demo/');
  const trigger = header.locator('[aria-controls="nav-features"]');
  await trigger.click();
  await expect(trigger).toHaveAttribute('aria-expanded', 'true');
  await expect(page.locator('#nav-features')).toBeVisible();
  await page.keyboard.press('Escape');
  await expect(trigger).toHaveAttribute('aria-expanded', 'false');
});

test('phone menu opens and offers sign-in', async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('/');
  const toggle = page.locator('.nav-toggle');
  await toggle.click();
  await expect(toggle).toHaveAttribute('aria-expanded', 'true');
  await expect(page.locator('#nav .nav-login')).toBeVisible();
  await expect(page.locator('#nav .nav-login')).toHaveAttribute('href', '/login');
});

test('pricing follows the chosen billing term', async ({ page }) => {
  await page.goto('/bang-gia/');
  const smart = page
    .locator('.plan')
    .filter({ has: page.getByRole('heading', { name: 'Sales Smart', exact: true }) })
    .locator('[data-price]');
  await expect(smart).toHaveText('785.000đ');
  await page.locator('.term-toggle').getByText('3 tháng').click();
  await expect(smart).toHaveText('1.310.000đ');
});

test('fonts are self-hosted and render Vietnamese', async ({ page }) => {
  await page.goto('/', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.fonts.ready);
  const fonts = await page.evaluate(() => ({
    body: getComputedStyle(document.body).fontFamily,
    loaded: [...document.fonts].filter((f) => f.status === 'loaded').map((f) => f.family),
  }));
  expect(fonts.body).toContain('Inter');
  expect(fonts.loaded.join(' ')).toContain('Inter');
});

test('font licences are published with the site', async ({ request }) => {
  for (const name of ['inter', 'inter-tight']) {
    const res = await request.get(`/fonts/${name}-OFL.txt`);
    expect(res.status()).toBe(200);
    expect(await res.text()).toContain('SIL Open Font License');
  }
});

test('feature screenshots open in a popup, not a new tab', async ({ page }) => {
  await page.goto('/tinh-nang/ban-hang-ai/');
  await page.locator('.fe-inspect figcaption a[data-lightbox]').click();
  const dialog = page.locator('dialog.lightbox');
  await expect(dialog).toBeVisible();
  await expect(page).toHaveURL(/\/tinh-nang\/ban-hang-ai\/$/);
  await page.keyboard.press('Escape');
  await expect(dialog).toBeHidden();
});
